80	// NewHandlerWithReadiness builds the same public HTTP surface as NewHandler but
81	// answers every request — including GET /healthz — with a 503 JSON error until
82	// ready reports that the database is open and the listener is accepting
83	// connections. Once ready, responses are byte-for-byte what NewHandler emits;
84	// readiness is one-way, so a later flip back is not part of the contract.
85	func NewHandlerWithReadiness(s *store.Store, ready func() bool) http.Handler {
86		h := NewHandler(s)
87		if ready == nil {
88			return h
89		}
90		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
91			if !ready() {
92				writeError(w, http.StatusServiceUnavailable, "service is not ready")
93				return
94			}
95			h.ServeHTTP(w, r)
96		})
97	}
