272	// decodeJSONBody enforces the strict POST contract shared by every JSON
273	// endpoint: Content-Type must be application/json, the body is capped at
274	// maxBatchBytes, it must contain exactly one JSON value, and no trailing data
275	// may follow it. Any violation writes a 400 JSON error and returns false; the
276	// caller returns immediately, so no handler reaches the store with malformed
277	// input and rejected requests write nothing.
278	func decodeJSONBody(w http.ResponseWriter, r *http.Request, dst any) bool {
279		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
280		if err != nil || mediaType != "application/json" {
281			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
282			return false
283		}
284	
285		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
286		dec := json.NewDecoder(r.Body)
287		if err := dec.Decode(dst); err != nil {
288			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
289			return false
290		}
291		// Reject trailing data after the JSON value.
292		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
293			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
294			return false
295		}
296		return true
297	}
