299	func handleRegisterDevice(s *store.Store, w http.ResponseWriter, r *http.Request) {
300		var req deviceRequest
301		if !decodeJSONBody(w, r, &req) {
302			return
303		}
304		if req.DeviceID == "" {
305			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
306			return
307		}
308	
309		created, err := s.RegisterDevice(req.DeviceID)
310		if err != nil {
311			writeError(w, http.StatusInternalServerError, "failed to register device")
312			return
313		}
314	
315		writeJSON(w, http.StatusOK, map[string]any{"deviceId": req.DeviceID, "created": created})
316	}
