347	func handleDeleteSession(s *store.Store, w http.ResponseWriter, r *http.Request) {
348		deviceID := r.PathValue("deviceId")   // route pattern + guard guarantee non-empty
349		sessionID := r.PathValue("sessionId") // route pattern + guard guarantee non-empty
350	
351		if err := s.DeleteSession(deviceID, sessionID); err != nil {
352			if errors.Is(err, store.ErrSessionNotFound) {
353				writeError(w, http.StatusNotFound, "session not found")
354				return
355			}
356			writeError(w, http.StatusInternalServerError, "failed to delete session")
357			return
358		}
359	
360		writeJSON(w, http.StatusOK, map[string]bool{"deleted": true})
361	}
