	}

	select {
	case res := <-ch:
		if !errors.Is(res.err, ErrStoreClosing) {
			t.Fatalf("err = %v, want ErrStoreClosing", res.err)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("close did not wake the poll")
