603	func TestSnapshotRetryAndConflictHTTP(t *testing.T) {
604		h, _ := newTestHandler(t)
605		seedDoc(t, h, "doc1", 1)
606	
607		w, body := postJSON(t, h, "/v1/documents/doc1/snapshots", `{"cursor":1,"state":{"v":1}}`)
608		if w.Code != http.StatusOK || body["created"] != true {
609			t.Fatalf("first = %d %v", w.Code, body)
