282		const n = 40
283		var wg sync.WaitGroup
284		var mu sync.Mutex
285		changed := 0
286		errs := make(chan error, n)
287		for i := 0; i < n; i++ {
288			wg.Add(1)
289			go func() {
290				defer wg.Done()
291				w, body := postJSON(t, h, url, map[string]any{"deviceId": "dev", "action": "revoke"})
292				if w.Code != http.StatusOK {
293					errs <- fmt.Errorf("status %d: %s", w.Code, w.Body.String())
294					return
295				}
296				if body["changed"] == true {
297					mu.Lock()
298					changed++
299					mu.Unlock()
300				}
301			}()
302		}
303		wg.Wait()
304		close(errs)
305		for err := range errs {
306			t.Fatal(err)
307		}
308		if changed != 1 {
309			t.Fatalf("changed reporters = %d, want 1", changed)
310		}
311	
312		// Concurrent grant vs. revoke settles into one coherent state: a repeat of
313		// the observed state is a no-op.
314		var wg2 sync.WaitGroup
315		statuses := make(chan int, 2)
316		wg2.Add(2)
317		for _, action := range []string{"grant", "revoke"} {
318			go func(action string) {
319				defer wg2.Done()
320				w, _ := postJSON(t, h, url, map[string]any{"deviceId": "dev", "action": action})
321				statuses <- w.Code
322			}(action)
323		}
324		wg2.Wait()
325		close(statuses)
326		for code := range statuses {
327			if code != http.StatusOK {
328				t.Fatalf("racing grant/revoke status = %d", code)
329			}
330		}
331		// Settle: force a known state, then confirm a repeat is a no-op.
332		w, _ := postJSON(t, h, url, map[string]any{"deviceId": "dev", "action": "revoke"})
333		if w.Code != http.StatusOK {
334			t.Fatal(w.Body.String())
