336		w, body := postJSON(t, h, url, map[string]any{"deviceId": "dev", "action": "revoke"})
337		if w.Code != http.StatusOK || body["changed"] != false {
338			t.Fatalf("settled revoke repeat = %d %v", w.Code, body)
339		}
340	}
