package store

import "sync"

// Subscriptions are the in-memory, push-only counterpart of long polling.
//
// A subscription belongs to a (document, device) pair — the device is the one
// owning the session that opened the connection. It receives exactly one
// signal per change-producing commit (PostChanges, ReplayChanges,
// MergeChange, RestoreSnapshot all signal through the same hook long polling
// uses). A permission write to the pair is signaled separately so the server
// can end a subscription with the permission-closed code instead of pushing
// another change.
//
// Like parked long polls, subscriptions leave no durable trace: nothing is
// written to the database, a disconnect simply unregisters, and closing the
// store broadcasts one final wakeup (the server maps it to a going-away
// close). Pushing never allocates a cursor or inserts a change row; the
// subscription layer only observes commits.
type subscription struct {
	// wakes receives one value on every change commit for the keyed document
	// and on a permission write to the keyed (document, device) pair. It is
	// buffered so a commit signal is never dropped or blocked while the
	// consumer is reading the log.
	wakes chan struct{}
}

func (s *Store) initSubscriptionsLocked() {
	if s.subs == nil {
		s.subs = make(map[subKey]map[uint64]*subscription)
	}
}

// AddSubscription registers an in-memory subscription for documentID as seen
// by deviceID and returns its wake channel and an unregister function. The
// unregister function is idempotent: a client disconnect, a permission close
// and a store close may all race to call it.
//
// If the store is already closing the channel is signaled immediately and
// unregister is a no-op, so a late subscriber parks on nothing.
func (s *Store) AddSubscription(documentID, deviceID string) (<-chan struct{}, func()) {
	ch := make(chan struct{}, 1)
	sub := &subscription{wakes: ch}
	key := subKey{document: documentID, device: deviceID}

	s.pollMu.Lock()
	defer s.pollMu.Unlock()
	if s.closed {
		close(ch)
		return ch, func() {}
	}
	s.subWG.Add(1)
	s.initSubscriptionsLocked()
	s.nextSubID++
	id := s.nextSubID
	set := s.subs[key]
	if set == nil {
		set = make(map[uint64]*subscription)
		s.subs[key] = set
	}
	set[id] = sub
	return ch, func() {
		s.pollMu.Lock()
		if set, ok := s.subs[key]; ok {
			if _, ok := set[id]; ok {
				delete(set, id)
				if len(set) == 0 {
					delete(s.subs, key)
				}
				s.pollMu.Unlock()
				s.subWG.Done()
				return
			}
		}
		s.pollMu.Unlock()
	}
}

// signalSubscribers wakes every subscription open on documentID. It is called
// only after a change-bearing transaction has committed, so when a woken
// subscription re-reads the log the new rows are visible. Callers hold no
// subscription lock; signals are non-blocking because the channels are
// buffered.
func (s *Store) signalSubscribers(documentID string) {
	s.pollMu.Lock()
	var targets []chan struct{}
	for key, set := range s.subs {
		if key.document != documentID {
			continue
		}
		for _, sub := range set {
			targets = append(targets, sub.wakes)
		}
	}
	s.pollMu.Unlock()

	for _, ch := range targets {
		select {
		case ch <- struct{}{}:
		default:
			// A signal the consumer has not drained yet is already pending;
			// the pending wake covers this commit too because the consumer
			// re-reads from its last observed cursor.
		}
	}
}

// signalPermissionSubscribers wakes only the subscriptions open on
// (documentID, deviceID), so the server can re-check the permission and close
// those whose access was revoked. Other devices' subscriptions are untouched.
func (s *Store) signalPermissionSubscribers(documentID, deviceID string) {
	s.pollMu.Lock()
	set := s.subs[subKey{document: documentID, device: deviceID}]
	targets := make([]chan struct{}, 0, len(set))
	for _, sub := range set {
		targets = append(targets, sub.wakes)
	}
	s.pollMu.Unlock()

	for _, ch := range targets {
		select {
		case ch <- struct{}{}:
		default:
		}
	}
}

// closeSubscriptions wakes every live subscription once, marks the registry
// closing so AddSubscription signals newcomers immediately, and waits for
// every subscription handler to unregister. Committed state is untouched; the
// wake is in-memory only and lets the server finish its WebSocket close
// handshake before the database handle goes away.
