				_ = conn.Close(wsCloseInternalError, "internal error")
				return
			}
			if writeErr := conn.WriteText(raw); writeErr != nil {
				return
			}
			position = changes[i].Cursor
		}

		// A full page means catch-up may not be drained yet; loop to read the
		// next page, still honoring a pending revoke/shutdown between pages.
		// An empty or partial page means the stream is caught up (an unknown
		// document included — it parks until its first commit), so block.
		if len(changes) == subscribePageLimit {
			if action := checkSignal(wakeCh, s, documentID, deviceID); action != subscriptionContinue {
				finishSubscription(conn, action)
				return
			}
			select {
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			default:
			}
			continue
		}

		select {
		case <-wakeCh:
			if action := classifyWake(s, documentID, deviceID); action != subscriptionContinue {
				finishSubscription(conn, action)
				return
			}
			// A plain commit: re-read from the last sent cursor.
		case <-clientGone:
			return
		case <-r.Context().Done():
			return
		}
	}
}

// checkSignal non-blockingly consumes a pending wake and classifies it; with
// no signal it returns subscriptionContinue immediately.
func checkSignal(wakeCh <-chan struct{}, s *store.Store, documentID, deviceID string) subscriptionAction {
	select {
	case <-wakeCh:
		return classifyWake(s, documentID, deviceID)
	default:
		return subscriptionContinue
	}
}

// finishSubscription sends the closing frame mandated by the resolved signal.
func finishSubscription(conn *wsConn, action subscriptionAction) {
	switch action {
	case subscriptionClosing:
		_ = conn.Close(wsCloseGoingAway, "going away")
	case subscriptionRevoked:
		_ = conn.Close(wsClosePermissionRevoked, "permission revoked")
	}
}

