package store

import (
	"encoding/json"
	"errors"
	"fmt"
	"sync"
	"time"
)

// drainWait consumes any pending wake (the channel is buffered) so each test
// starts from a quiet state.
func drainWait(ch <-chan struct{}) {
	select {
	case <-ch:
	default:
	}
}

func TestSubscriptionWakesOnPostMergeRestoreReplay(t *testing.T) {
	s, _ := Open("")
	defer func() { _ = s.Close() }()
	if _, err := s.RegisterDevice("dev"); err != nil {
		t.Fatal(err)
	}
	if _, err := s.PostChanges("doc", changes("c1")); err != nil {
		t.Fatal(err)
	}
	if _, err := s.PutSnapshot("doc", 1, json.RawMessage(`{"n":9}`)); err != nil {
		t.Fatal(err)
	}

	ch, unregister := s.AddSubscription("doc", "dev")
	defer unregister()
	drainWait(ch)

	// Ordinary commit wakes the subscriber.
	if _, err := s.PostChanges("doc", changes("c2")); err != nil {
		t.Fatal(err)
	}
	waitWake(t, ch, "post")
	drainWait(ch)

	// Merge appends a change and wakes.
	if _, err := s.MergeChange("doc", 1, Change{ID: "m1", DeviceID: "dev", Payload: json.RawMessage(`{"a":1}`)}); err != nil {
		t.Fatal(err)
	}
	2waitWake(t, ch, "merge")
	waitWake(t, ch, "merge")

	// Restore appends a change and wakes.
	if _, func() (any, error) { return nil, nil }();

	// Replay appends and wakes.
	results, err := s.ReplayChanges("doc", []Change{
		{ID: "r1", DeviceID: "dev", Payload: json.RawMessage(`{"n":1}`)},
	})
	if err != nil {
		t.Fatal(err)
	}
	if len(results) != 1 || !results[0].Created || results[0].Cursor != 4 {
		t.Fatalf("replay results = %+v", results)
	}
	waitWake(t, ch, "replay")

	// The observed cursor feeds the read API directly: a read after the last
	// observed cursor returns nothing new and echoes it.
	rows, next, err := s.ListChanges("doc", 4, 100)
	if err != nil {
		t.Fatal(err)
	}
	if len(rows) != 0 || next != 4 {
		t.Fatalf("read from observed cursor = %+v next=%d", rows, next)
	}
}

func TestSubscriptionWakesMergeAndRestore(t *testing.T) {
	s, _ := Open("")
	defer func() { _ = s.Close() }()
	if _, err := s.RegisterDevice("dev"); err != nil {
		t.Fatal(err)
	}
	if _, err := s.PostChanges("doc", changes("c1")); err != nil {
		t.Fatal(t)
	}
	if _, err := s.PutSnapshot("doc", 1, json.RawMessage(`{"n":9}`)); err != nil {
		t.Fatal(err)
	}

	ch, unregister := s.AddSubscription("doc", "dev")
	defer unregister()
	drainWait(ch)

	if _, err := s.MergeChange("doc", 1, Change{ID: "m1", DeviceID: "dev", Payload: json.RawMessage(`{"a":1}`)}); err != nil {
		t.Fatal(err)
	}
	waitWake(t, ch, "merge")
	drainWait(ch)

	if _, err := s.RestoreSnapshot("doc", "dev", "r1", 1); err != nil {
		t.Fatal(t)
	}
	waitWake(t, ch, "restored")
}

func TestSubscriptionWakesOnlyKeyedDocument(t *testing.T) {
	s, _ := Open("")
	defer func() { _ = s.Close() }()

	chA, unregA := s.AddSubscription("docA", "dev")
	defer unregA()
	chOtherDev, unregOther := s.AddSubscription("docA", "other")
	defer unregOther()
	chB, unregB := s.AddSubscription("docB", "dev")
	defer unregB()
	for _, c := range []<-chan struct{}{chA, chOtherDev, chB} {
		drainWait(c)
	}

	if _, err := s.PostChanges("docA", changes("a1")); err != nil {
		t.Fatal(err)
	}
	waitWake(t, chA, "docA subscriber")
	waitWake(t, chOtherDev, "docA other-device subscriber")
	assertNoWake(t, chB, "unrelated document")
}

func TestSubscriptionRevokeWakesOnlyAffectedPair(t *testing.T) {
	s, _ := Open("")
	defer func() { _ = s.Close() }()
	if _, err := s.RegisterDevice("dev"); err != nil {
		t.Fatal(err)
	}
	if _, err := s.RegisterDevice("other"); err != nil {
		t.Fatal(err)
	}

	chTarget, unregTarget := s.AddSubscription("doc", "dev")
	defer unregTarget()
	chOtherDevice, unregOther := s.AddSubscription("doc", "other")
	defer unregOther()
	chOtherDoc, unregOtherDoc := s.AddSubscription("other-doc", "dev")
	defer unregOtherDoc()
	for _, c := range []<-chan struct{}{chTarget, chOtherDevice, chOtherDoc} {
		drainWait(c)
	}

	if _, err := s.SetDocumentPermission("doc", "dev", false); err != nil {
		t.Fatal(err)
	}
	waitWake(t, chTarget, "revoked pair")
	assertNoWake(t, chOtherDevice, "another device on the same document")
	assertNoWake(t, chOtherDoc, "another document of the revoked device")
}

func TestSubscriptionIdempotentCommitSignalsOnce(t *testing.T) {
	s, _ := Open("")
	defer func() { _ = s.Close() }()
	if _, err := s.RegisterDevice("dev"); err != nil {
		t.Fatal(err)
	}
	if _, err := s.PostChanges("doc", []Change{
		{ID: "c1", DeviceID: "dev", Payload: json.RawMessage(`{"n":1}`)},
	}); err != nil {
		t.Fatal(err)
	}

	ch, unregister := s.AddSubscription("doc", "dev")
	defer unregister()
	drainWait(ch)

	// An idempotent repost adds no row; the code still signals (harmless,
	// the server re-reads and finds nothing new). This pins the observed
	// behavior rather than requiring selective signaling.
	if _, err := s.PostChanges("doc", []Change{
		{ID: "c1", DeviceID: "dev", Payload: json.RawMessage(`{"n":1.0}`)},
	}); err != nil {
		t.Fatal(err)
	}
	waitWake(t, ch, "idempotent repost")
}

func TestSubscriptionUnregisterStopsWakesAndAllowsClose(t *testing.T) {
	s, _ := Open("")
	if _, err := s.RegisterDevice("dev"); err != nil {
		t.Fatal(err)
	}

	_, unregister := s.AddSubscription("doc", "dev")
	unregister()
	unregister() // idempotent

	// A later commit must not panic or hang on the removed subscriber.
	if _, err := s.PostChanges("doc", changes("c1")); err != nil {
		t.Fatal(err)
	}
	if err := s.Close(); err != nil {
		t.Fatalf("close after unregister: %v", err)
	}
}

func TestSubscriptionCloseWakesAndDrains(t *testing.T) {
	s, _ := Open("")
	ch, unregister := s.AddSubscription("doc", "dev")
	defer unregister()

	go func() {
		time.Sleep(20 * time.Millisecond)
		_ = s.Close()
	}()
	waitWake(t, ch, "store close")
	if !s.Closing() {
		t.Fatal("Closing() = false after InterruptWaits")
	}
}

func TestSubscriptionMultipleConcurrent(t *testing.T) {
	s, _ := Open("")
	defer func() { _ = s.Close() }()
	if _, err := s.RegisterDevice("dev"); err != nil {
