	if _, err := s.PostChanges("doc", changes("c2")); err != nil {
		t.Fatal(err)
	}
	waitWake(t, ch, "post")
	drainWait(ch)

	// Merge appends a change.
	if _, err := s.MergeChange("doc", 1, Change{ID: "m1", DeviceID: "dev-1", Payload: json.RawMessage(`{"a":1}`)}); err != nil {
		t.Fatal(err)
	}
	waitWake(t, ch, "merge")
	drainWait(ch)

