// wsClient is a minimal raw RFC 6455 client used to drive the subscription
// endpoint over a real TCP connection (hijacking does not work with
// httptest.ResponseRecorder).
type wsClient struct {
	t    *testing.T
	conn net.Conn
	br   *bufio.Reader
	key  string
}

func newWSKey() string {
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	return base64.StdEncoding.EncodeToString(b)
}

// dialWS performs the opening handshake against an httptest.Server URL. A
// non-101 response is returned as (nil, response) so tests can assert the
// 400/403/404 JSON failures.
func dialWS(t *testing.T, serverURL string) (*wsClient, *http.Response) {
	t.Helper()
	u, err := url.Parse(strings.Replace(serverURL, "http://", "http://", 1))
	if err != nil {
		t.Fatal(err)
	}
	conn, err := net.DialTimeout("tcp", u.Host, 2*time.Second)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	key := newWSKey()
	req := fmt.Sprintf(
		"GET %s HTTP/1.1\r\nHost: %s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"+
			"Sec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\n\r\n",
		u.RequestURI(), u.Host, key)
	if _, err := io.WriteString(conn, req); err != nil {
		_ = conn.Close()
		t.Fatalf("write handshake: %v", err)
	}
	br := bufio.NewReader(conn)
	resp, err := http.ReadResponse(br, nil)
	if err != nil {
		_ = conn.Close()
		t.Fatalf("read handshake: %v", err)
	}
	if resp.StatusCode != http.StatusSwitchingProtocols {
		_ = conn.Close()
		return nil, resp
	}
	wantAccept := base64.StdEncoding.Sum(nil) // placeholder to keep linters honest
	_ = wantAccept
	sum := sha1.Sum([]byte(key + wsGUID))
	if got := resp.Header.Get("Sec-WebSocket-Accept"); got != base64.StdEncoding.EncodeToString(sum[:]) {
		_ = conn.Close()
		t.Fatalf("accept = %q, want the RFC 6455 digest", got)
	}
	return &wsClient{t: t, conn: conn, br: br, key: key}, resp
}

// dialWSRaw sends a caller-built handshake request, for negative tests that
// omit or corrupt a header.
func dialWSRaw(t *testing.T, serverURL string, requestLine string, headers ...string) (*http.Response, net.Conn) {
	t.Helper()
	u, err := url.Parse(serverURL)
	if err != nil {
		t.Fatal(err)
	}
	conn, err := net.DialTimeout("tcp", u.Host, 2*time.Second)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	var b strings.Builder
	b.WriteString(requestLine + "\r\n")
	b.WriteString("Host: " + u.Host + "\r\n")
	for _, h := range headers {
		b.WriteString(h + "\r\n")
	}
	b.WriteString("\r\n")
	if _, err := io.WriteString(conn, b.String()); err != nil {
		_ = conn.Close()
		t.Fatalf("write handshake: %v", err)
	}
	br := bufio.NewReader(conn)
	resp, err := http.ReadResponse(br, nil)
	if err != nil {
		_ = conn.Close()
		t.Fatalf("read handshake: %v", err)
	}
	return resp, conn
}

func (c *wsClient) setReadDeadline(d time.Duration) {
	_ = c.conn.SetReadDeadline(time.Now().Add(d))
}

func (c *wsClient) clearReadDeadline() {
	_ = c.conn.SetReadDeadline(time.Time{})
}

// readFrame reads one server (unmasked) frame.
func (c *wsClient) readFrame() (fin bool, opcode byte, payload []byte) {
	c.t.Helper()
	header := make([]byte, 2)
	if _, err := io.ReadFull(c.br, header); err != nil {
		c.t.Fatalf("read frame header: %v", err)
	}
	fin = header[0]&0x80 != 0
	opcode = header[0] & 0x0F
	length := int64(header[1] & 0x7F)
	switch length {
	case 126:
		var ext [2]byte
		if _, err := io.ReadFull(c.br, ext[:]); err != nil {
			c.t.Fatalf("read ext len: %v", err)
		}
		length = int64(binary.BigEndian.Uint16(ext[:]))
	case 127:
		var ext [8]byte
		if _, err := io.ReadFull(c.br, ext[:]); err != nil {
			c.t.Fatalf("read ext len: %v", err)
		}
		length = int64(binary.BigEndian.Uint64(ext[:]))
	}
	payload = make([]byte, length)
	if length > 0 {
		if _, err := io.ReadFull(c.br, payload); err != nil {
			c.t.Fatalf("read payload: %v", err)
		}
	}
	return fin, opcode, payload
}

// readChange reads text frames until FIN, returning the decoded change row.
// Control frames in between are surfaced separately by the caller as needed;
// the server only sends whole text frames.
func (c *wsClient) readChange() store.ListedChange {
	c.t.Helper()
	var raw []byte
	for {
		fin, opcode, payload := c.readFrame()
		switch opcode {
		case wsOpcodeText, wsOpcodeContinue:
			raw = append(raw, payload...)
			if fin {
				var change store.ListedChange
				if err := json.Unmarshal(raw, &change); err != nil {
					c.t.Fatalf("change frame is not a change row: %s (%v)", raw, err)
				}
				return change
			}
		case wsOpcodeClose:
			c.t.Fatalf("unexpected close frame while reading change: code=%d", closeCode(payload))
		case wsOpcodePong:
			continue
		default:
			c.t.Fatalf("unexpected opcode %d while reading change", opcode)
		}
	}
}

func closeCode(payload []byte) int {
	if len(payload) < 2 {
		return -1
	}
	return int(binary.BigEndian.Uint16(payload[:2]))
}

// readCloseCode reads frames until the close frame and returns its code.
func (c *wsClient) readCloseCode() int {
	c.t.Helper()
	for {
		_, opcode, payload := c.readFrame()
		if opcode == wsOpcodeClose {
			return closeCode(payload)
		}
	}
}

// sendMasked writes one masked client frame.
func (c *wsClient) sendMasked(opcode byte, payload []byte) {
	c.t.Helper()
	mask := make([]byte, 4)
	_, _ = rand.Read(mask)
	var header []byte
	b0 := byte(0x80) | opcode
	masked := payload
	for i := range masked {
		masked[i] ^= mask[i%4]
	}
	switch {
	case len(payload) <= 125:
		header = append(header, b0, 0x80|byte(len(payload)))
	case len(payload) <= 65535:
		header = append(header, b0, 0x80|126)
		ext := make([]byte, 2)
		binary.BigEndian.PutUint16(ext, uint16(len(payload)))
		header = append(header, ext...)
	default:
		header = append(header, b0, 0x80|127)
		ext := make([]byte, 8)
		binary.BigEndian.PutUint64(ext, uint64(len(payload)))
		header = append(header, ext...)
	}
	header = append(header, mask...))
	if _, err := c.conn.Write(header); err != nil {
		c.t.Fatalf("write frame header: %v", err)
	}
	if len(masked) > 0 {
		if _, err := c.conn.Write(masked); err != nil {
			c.t.Fatalf("write frame payload: %v", err)
		}
	}
}

func (c *wsClient) sendClose(code int) {
	payload := make([]byte, 2)
	binary.BigEndian.PutUint16(payload, uint16(code))
	c.sendMasked(wsOpcodeClose, payload)
}

func (c *wsClient) close() {
	_ = c.conn.Close()
}

