			// discarded; the client cannot mutate the log over it.
		}
	}()

	position := cursor
	first := true
	for {
		if !first {
			// Park until a commit, a permission write or the termination
			// signal wakes us. r.Context() covers a non-shutdown cancel; the
			// read pump covers a client disconnect.
			select {
			case <-wakeCh:
				// Drain any coalesced follow-up signal as well; the flush
				// below and the state checks after it reconcile every case.
				select {
				case <-wakeCh:
				default:
				}
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			}
			if s.Closing() {
				_ = conn.Close(wsCloseGoingAway, "going away")
				return
			}
		}
		first = false

		// Flush phase: page every change past position in cursor order. A
		// termination signal is honored between pages/rows so a large
		// catch-up cannot delay the 1001. A revoke is checked only once the
		// committed tail is drained (after the inner loop), so changes
		// committed while still authorized go out first.
		for {
			if s.Closing() {
				_ = conn.Close(wsCloseGoingAway, "going away")
				return
			}
			select {
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			default:
			}

			changes, _, err := s.ListChanges(documentID, position, subscribePageLimit)
			if err != nil {
				_ = conn.Close(wsCloseInternalError, "internal error")
				return
			}
			for i := range changes {
				if s.Closing() {
					_ = conn.Close(wsCloseGoingAway, "going away")
					return
				}
				raw, marshalErr := json.Marshal(changes[i])
				if marshalErr != nil {
					_ = conn.Close(wsCloseInternalError, "internal error")
					return
				}
				if writeErr := conn.WriteText(raw); writeErr != nil {
					return
				}
				position = changes[i].Cursor
			}
			if len(changes) < subscribePageLimit {
				break
			}
		}

		// Caught up. If the wake was a revoke (possibly coalesced with the
		// last commit, which has just been flushed), end the subscription;
		// otherwise loop back and park for the next commit.
		authorized, err := s.DocumentAuthorized(documentID, deviceID)
		if err != nil {
			_ = conn.Close(wsCloseInternalError, "internal error")
			return
		}
		if !authorized {
			_ = conn.Close(wsClosePermissionRevoked, "permission revoked")
			return
		}
	}
