24	// wsClient is a minimal raw RFC 6455 client used to drive the subscription
25	// endpoint over a real TCP connection (HTTP hijacking does not work with
26	// httptest.ResponseRecorder).
27	type wsClient struct {
28		t    *testing.T
29		conn net.Conn
