39	// dialWS performs the opening handshake against an httptest.Server URL. A
40	// non-101 response is returned as (nil, response) so tests can assert the
41	// 400/403/404 JSON failures.
42	func dialWS(t *testing.T, serverURL string) (*wsClient, *http.Response) {
43		t.Helper()
44		u, err := url.Parse(serverURL)
45		if err != nil {
46			t.Fatal(err)
47		}
48		conn, err := net.DialTimeout("tcp", u.Host, 2*time.Second)
49		if err != nil {
50			t.Fatalf("dial: %v", err)
51		}
52		key := newWSKey()
53		req := fmt.Sprintf(
54			"GET %s HTTP/1.1\r\nHost: %s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"+
55				"Sec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\n\r\n",
56			u.RequestURI(), u.Host, key)
57		if _, err := io.WriteString(conn, req); err != nil {
58			_ = conn.Close()
59			t.Fatalf("write handshake: %v", err)
60		}
61		br := bufio.NewReader(conn)
62		resp, err := http.ReadResponse(br, nil)
63		if err != nil {
64			_ = conn.Close()
65			t.Fatalf("read handshake: %v", err)
66		}
67		if resp.StatusCode != http.StatusSwitchingProtocols {
68			_ = conn.Close()
69			return nil, resp
70		}
71		sum := sha1.Sum([]byte(key + wsGUID))
72		if got := resp.Header.Get("Sec-WebSocket-Accept"); got != base64.StdEncoding.EncodeToString(sum[:]) {
73			_ = conn.Close()
74			t.Fatalf("accept = %q, want the RFC 6455 digest", got)
75		}
76		return &wsClient{t: t, conn: conn, br: br}, resp
77	}
