79	// dialWSRaw sends a caller-built handshake request, for negative tests that
80	// omit or corrupt a header.
81	func dialWSRaw(t *testing.T, serverURL, requestTarget string, headers ...string) (*http.Response, net.Conn) {
82		t.Helper()
83		u, err := url.Parse(serverURL)
