111	// readFrame reads one server (unmasked) frame.
112	func (c *wsClient) readFrame() (fin bool, opcode byte, payload []byte) {
113		c.t.Helper()
114		header := make([]byte, 2)
115		if _, err := io.ReadFull(c.br, header); err != nil {
116			c.t.Fatalf("read frame header: %v", err)
117		}
118		fin = header[0]&0x80 != 0
119		opcode = header[0] & 0x0F
120		length := int64(header[1] & 0x7F)
121		switch length {
122		case 126:
123			var ext [2]byte
124			if _, err := io.ReadFull(c.br, ext[:]); err != nil {
125				c.t.Fatalf("read ext len: %v", err)
126			}
127			length = int64(binary.BigEndian.Uint16(ext[:]))
128		case 127:
129			var ext [8]byte
130			if _, err := io.ReadFull(c.br, ext[:]); err != nil {
131				c.t.Fatalf("read ext len: %v", err)
132			}
133			length = int64(binary.BigEndian.Uint64(ext[:]))
134		}
135		payload = make([]byte, length)
136		if length > 0 {
137			if _, err := io.ReadFull(c.br, payload); err != nil {
138				c.t.Fatalf("read payload: %v", err)
139			}
140		}
141		return fin, opcode, payload
142	}
143	
144	func closeCode(payload []byte) int {
145		if len(payload) < 2 {
146			return -1
147		}
148		return int(binary.BigEndian.Uint16(payload[:2]))
149	}
