151	// readFrameMaybe is the non-fatal variant used by negative assertions: with a
152	// read deadline already set it reports ok=false on a timeout/EOF instead of
153	// failing the test.
154	func (c *wsClient) readFrameMaybe() (fin bool, opcode byte, payload []byte, ok bool) {
155		header := make([]byte, 2)
156		if _, err := io.ReadFull(c.br, header); err != nil {
157			return false, 0, nil, false
158		}
159		fin = header[0]&0x80 != 0
160		opcode = header[0] & 0x0F
161		length := int64(header[1] & 0x7F)
162		switch length {
163		case 126:
164			var ext [2]byte
165			if _, err := io.ReadFull(c.br, ext[:]); err != nil {
166				return false, 0, nil, false
167			}
168			length = int64(binary.BigEndian.Uint16(ext[:]))
169		case 127:
170			var ext [8]byte
171			if _, err := io.ReadFull(c.br, ext[:]); err != nil {
172				return false, 0, nil, false
173			}
174			length = int64(binary.BigEndian.Uint64(ext[:]))
175		}
176		payload = make([]byte, length)
177		if length > 0 {
178			if _, err := io.ReadFull(c.br, payload); err != nil {
179				return false, 0, nil, false
180			}
181		}
182		return fin, opcode, payload, true
183	}
184	
185	// readChange reads the next complete text message and decodes one change row.
186	// The server only ever sends whole (FIN) text frames; pongs are skipped.
187	func (c *wsClient) readChange() store.ListedChange {
188		c.t.Helper()
189		for {
190			fin, opcode, payload := c.readFrame()
191			switch opcode {
192			case wsOpcodeText:
193				if !fin {
194					c.t.Fatal("server sent a fragmented text frame")
195				}
196				var change store.ListedChange
197				if err := json.Unmarshal(payload, &change); err != nil {
198					c.t.Fatalf("text frame is not a change row: %s (%v)", payload, err)
199				}
200				return change
201			case wsOpcodePong:
202				continue
203			case wsOpcodeClose:
204				c.t.Fatalf("unexpected close frame while reading change: code=%d", closeCode(payload))
205			default:
206				c.t.Fatalf("unexpected opcode %d while reading change", opcode)
207			}
208		}
209	}
210	
211	// readCloseCode reads frames until the close frame and returns its code.
212	func (c *wsClient) readCloseCode() int {
213		c.t.Helper()
214		for {
215			_, opcode, payload := c.readFrame()
216			if opcode == wsOpcodeClose {
217				return closeCode(payload)
218			}
219		}
220	}
221	
222	// sendMasked writes one masked client frame.
223	func (c *wsClient) sendMasked(opcode byte, payload []byte) {
224		c.t.Helper()
225		mask := make([]byte, 4)
226		_, _ = rand.Read(mask)
227		masked := append([]byte(nil), payload...)
228		for i := range masked {
229			masked[i] ^= mask[i%4]
230		}
231		var header []byte
232		b0 := byte(0x80) | opcode
233		switch {
234		case len(payload) <= 125:
235			header = append(header, b0, 0x80|byte(len(payload)))
236		case len(payload) <= 65535:
237			header = append(header, b0, 0x80|126)
238			ext := make([]byte, 2)
239			binary.BigEndian.PutUint16(ext, uint16(len(payload)))
240			header = append(header, ext...)
241		default:
242			header = append(header, b0, 0x80|127)
243			ext := make([]byte, 8)
244			binary.BigEndian.PutUint64(ext, uint64(len(payload)))
245			header = append(header, ext...)
246		}
247		header = append(header, mask...)
248		if _, err := c.conn.Write(header); err != nil {
249			c.t.Fatalf("write frame header: %v", err)
250		}
251		if len(masked) > 0 {
252			if _, err := c.conn.Write(masked); err != nil {
253				c.t.Fatalf("write frame payload: %v", err)
254			}
255		}
256	}
257	
258	func (c *wsClient) sendText(payload string) { c.sendMasked(wsOpcodeText, []byte(payload)) }
259	func (c *wsClient) sendPing()               { c.sendMasked(wsOpcodePing, nil) }
260	
261	func (c *wsClient) setReadDeadline(d time.Duration) {
262		_ = c.conn.SetReadDeadline(time.Now().Add(d))
263	}

